// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();
        bool lastPlayWon = (c.pot() == 0);

        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();

        bool invariantHolds = ((c.pot() == 0) == lastPlayWon);
        assertTrue(invariantHolds);
    }
}
